<template>
  <div class="page-root">
  <!-- Skeleton -->
  <div v-if="store.loading" class="skeleton-wrap">
    <div class="sk sk--header" />
    <div class="sk sk--image" />
    <div class="sk sk--line w80" />
    <div class="sk sk--line w60" />
    <div class="sk sk--line w40" />
  </div>

  <!-- Product -->
  <div v-else-if="product" class="product">

    <!-- Header -->
    <div class="product__header">
      <button class="product__header-btn" @click="router.back()">
        <svg width="24" height="24" viewBox="0 0 24 24" fill="none">
          <path d="M15 19L8 12L15 5" stroke="#111D33" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/>
        </svg>
      </button>
      <span class="product__header-title">{{ shortName }}</span>

      <div class="product__header-right" @click="goToMyhelp">
        <button class="product__header-btn">
         <svg width="24" height="24" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
<path d="M11.25 12V1.5" stroke="#111D33" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/>
<path d="M8.25 4.5L11.25 1.5L14.25 4.5" stroke="#111D33" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/>
<path d="M17.25 12C18.3938 12.6862 19.3404 13.6569 19.9976 14.8177C20.6548 15.9784 21.0001 17.2896 21 18.6234V22.5" stroke="#111D33" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/>
<path d="M7.5 8.25H6C5.80109 8.25 5.61032 8.32902 5.46967 8.46967C5.32902 8.61032 5.25 8.80109 5.25 9V18.75" stroke="#111D33" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/>
<path d="M15.0897 22.5L13.0028 19.3125C12.7581 18.8821 12.6936 18.3723 12.8233 17.8945C12.953 17.4167 13.2665 17.0096 13.6953 16.762C14.1241 16.5144 14.6334 16.4465 15.1121 16.5731C15.5907 16.6996 15.9999 17.0104 16.2503 17.4375L17.2516 18.9666V9C17.2516 8.80109 17.1726 8.61032 17.0319 8.46967C16.8913 8.32902 16.7005 8.25 16.5016 8.25H15.0016" stroke="#111D33" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/>
</svg>

        </button>
        <button class="product__header-btn" @click="goToNotifications">
          <svg width="24" height="24" viewBox="0 0 24 24" fill="none">
            <path d="M9 21H15" stroke="#111D33" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/>
            <path d="M5.2533 9.75C5.2533 7.95979 5.96446 6.2429 7.23033 4.97703C8.4962 3.71116 10.2131 3 12.0033 3C13.7935 3 15.5104 3.71116 16.7763 4.97703C18.0421 6.2429 18.7533 7.95979 18.7533 9.75C18.7533 13.1081 19.5314 15.8063 20.1502 16.875C20.2159 16.9888 20.2505 17.1179 20.2507 17.2493C20.2508 17.3808 20.2164 17.5099 20.1508 17.6239C20.0853 17.7378 19.991 17.8325 19.8774 17.8985C19.7637 17.9645 19.6347 17.9995 19.5033 18H4.5033C4.37203 17.9992 4.24327 17.964 4.12988 17.8978C4.0165 17.8317 3.92246 17.7369 3.85716 17.6231C3.79187 17.5092 3.75761 17.3801 3.75781 17.2489C3.75801 17.1176 3.79266 16.9887 3.8583 16.875C4.47611 15.8063 5.2533 13.1072 5.2533 9.75Z" stroke="#111D33" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/>
          </svg>
        </button>
      </div>
    </div>

    <!-- Image block -->
    <div class="product__image-wrap">
      <div class="product__gallery">
        <button class="product__wishlist" @click="toggleFavourite(product)">
          <svg width="20" height="20" viewBox="0 0 24 24" fill="none">
            <path d="M12 21.35l-1.45-1.32C5.4 15.36 2 12.28 2 8.5 2 5.42 4.42 3 7.5 3c1.74 0 3.41.81 4.5 2.09C13.09 3.81 14.76 3 16.5 3 19.58 3 22 5.42 22 8.5c0 3.78-3.4 6.86-8.55 11.54L12 21.35z"
              :fill="isWishlisted ? '#00C27C' : 'none'"
              :stroke="isWishlisted ? '#00C27C' : '#C4C4C4'"
              stroke-width="1.5"/>
          </svg>
        </button>

        <div class="product__slides" @touchstart="touchStart" @touchend="touchEnd">
          <div class="product__slides-track" :style="{ transform: `translateX(-${currentSlide * 100}%)` }">
            <div v-for="(img, i) in images" :key="i" class="product__slide">
              <img :src="img" :alt="product.name" />
            </div>
          </div>
        </div>
      </div>

      <div class="product__dots">
        <span
          v-for="(_, i) in images"
          :key="i"
          class="product__dot"
          :class="{ active: currentSlide === i }"
          @click="currentSlide = i"
        />
      </div>
    </div>

    <!-- Content -->
    <div class="product__content">

      <!-- Оранжевый: ожидание менеджера -->
      <div class="product__status-banner" v-if="reserveStatus === 'pending'">
        <svg width="18" height="18" viewBox="0 0 24 24" fill="none">
          <path d="M12 22C17.5228 22 22 17.5228 22 12C22 6.47715 17.5228 2 12 2C6.47715 2 2 6.47715 2 12C2 17.5228 6.47715 22 12 22Z" stroke="#F59E0B" stroke-width="1.5"/>
          <path d="M12 8V12" stroke="#F59E0B" stroke-width="1.5" stroke-linecap="round"/>
          <path d="M12 16H12.01" stroke="#F59E0B" stroke-width="2" stroke-linecap="round"/>
        </svg>
        <span>Ожидаем подтверждение менеджера...</span>
      </div>

      <!-- Зелёный: таймер после подтверждения -->
      <div class="product__timer product__timer--green" v-if="reserveStatus === 'confirmed'">
        <svg width="18" height="18" viewBox="0 0 24 24" fill="none">
          <path d="M12 22C17.5228 22 22 17.5228 22 12C22 6.47715 17.5228 2 12 2C6.47715 2 2 6.47715 2 12C2 17.5228 6.47715 22 12 22Z" stroke="#00C27C" stroke-width="1.5"/>
          <path d="M12 7V12L15 15" stroke="#00C27C" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/>
        </svg>
        <span>До истечения резерва осталось <b>{{ timerDisplay }}</b></span>
      </div>

      <!-- Красный: истёк через 5 минут -->
      <div class="product__timer product__timer--red" v-if="reserveStatus === 'expired'">
        <svg width="18" height="18" viewBox="0 0 24 24" fill="none">
          <path d="M19 11H5M19 11C20.1046 11 21 11.8954 21 13V19C21 20.1046 20.1046 21 19 21H5C3.89543 21 3 20.1046 3 19V13C3 11.8954 3.89543 11 5 11M19 11V9C19 7.93913 18.5786 6.92172 17.8284 6.17157C17.0783 5.42143 16.0609 5 15 5M5 11V9C5 7.93913 5.42143 6.92172 6.17157 6.17157C6.92172 5.42143 7.93913 5 9 5M15 5C15 5 15 3 12 3C9 3 9 5 9 5M15 5H9" stroke="#EF4444" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/>
          <circle cx="12" cy="16" r="1.5" fill="#EF4444"/>
        </svg>
        <span>До истечения резерва осталось <b>{{ timerDisplay }}</b></span>
      </div>

      <!-- Название и цена -->
      <div class="product__name-section">
        <h2 class="product__name">{{ product.name }}</h2>
        <div class="product__price-row">
          <span class="product__price">{{ formatPrice(product.price) }} ₸</span>
          <span v-if="product.old_price" class="product__old-price">{{ formatPrice(product.old_price) }} ₸</span>
        </div>
      </div>

      <!-- Информация о товаре -->
      <div class="product__section">
        <h3 class="product__section-title">Информация о товаре</h3>
        <div class="product__info-list">
          <div class="product__info-row" v-if="categoryName">
  <span class="product__info-label">Категория</span>
  <span class="product__info-sep">:</span>
  <span class="product__info-value">{{ categoryName }}</span>
</div>
          <div class="product__info-row" v-if="product.brand">
            <span class="product__info-label">Бренд</span>
            <span class="product__info-sep">:</span>
            <span class="product__info-value">{{ product.brand }}</span>
          </div>
          <div class="product__info-row" v-if="product.location">
            <span class="product__info-label">Доступно в</span>
            <span class="product__info-sep">:</span>
            <span class="product__info-value">{{ product.location }}</span>
          </div>
        </div>
      </div>

      <!-- Помощь фонду — показываем только если fund_name заполнен -->
      <div class="product__section" v-if="product.fund_name">
        <h3 class="product__section-title">Помощь фонду</h3>
        <div class="product__fund">
          <div class="product__fund-top" @click="goToFond">
            <div class="product__fund-logo">
              <img
                v-if="product.fund_logo"
                :src="product.fund_logo"
                :alt="product.fund_name"
              />
              <div v-else class="product__fund-logo-ph">
                <svg width="28" height="28" viewBox="0 0 24 24" fill="none">
                  <path d="M12 21.35l-1.45-1.32C5.4 15.36 2 12.28 2 8.5 2 5.42 4.42 3 7.5 3c1.74 0 3.41.81 4.5 2.09C13.09 3.81 14.76 3 16.5 3 19.58 3 22 5.42 22 8.5c0 3.78-3.4 6.86-8.55 11.54L12 21.35z" fill="#00C27C"/>
                </svg>
              </div>
            </div>
            <div class="product__fund-info">
              <p class="product__fund-name">{{ product.fund_name }}</p>
              <p class="product__fund-desc">{{ product.fund_description }}</p>
            </div>
          </div>
          <div class="product__fund-bottom">
            <span class="product__fund-label">Поступит в фонд</span>
            <span class="product__fund-amount">{{ formatPrice(product.fund_amount) }} ₸</span>
          </div>
        </div>
      </div>

      <!-- Описание -->
      <div class="product__section" v-if="product.description">
        <h3 class="product__section-title">Описание</h3>
        <p class="product__desc" :class="{ 'product__desc--clamped': !descExpanded }">
          {{ product.description }}
        </p>
        <button v-if="!descExpanded" class="product__expand" @click="descExpanded = true">
          Развернуть
        </button>
      </div>

      <!-- Характеристики -->
   

      <div style="height:100px" />
    </div>

    <!-- Кнопка -->
    <div class="product__footer">
      <button
        v-if="!isReserved"
        class="product__reserve"
        :disabled="!product.stock || product.stock === 0"
        @click="onReserve"
      >
        <span v-if="product.stock > 0">
          Зарезервировать ({{ reservedCount }}/{{ product.stock }})
        </span>
        <span v-else>Нет в наличии</span>
      </button>
      <button
        v-else-if="reserveStatus === 'expired'"
        class="product__notify"
        @click="onNotify"
      >
        <svg width="20" height="20" viewBox="0 0 24 24" fill="none">
          <path d="M9 21H15" stroke="#fff" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/>
          <path d="M5.2533 9.75C5.2533 7.95979 5.96446 6.2429 7.23033 4.97703C8.4962 3.71116 10.2131 3 12.0033 3C13.7935 3 15.5104 3.71116 16.7763 4.97703C18.0421 6.2429 18.7533 7.95979 18.7533 9.75C18.7533 13.1081 19.5314 15.8063 20.1502 16.875C20.2159 16.9888 20.2505 17.1179 20.2507 17.2493C20.2508 17.3808 20.2164 17.5099 20.1508 17.6239C20.0853 17.7378 19.991 17.8325 19.8774 17.8985C19.7637 17.9645 19.6347 17.9995 19.5033 18H4.5033C4.37203 17.9992 4.24327 17.964 4.12988 17.8978C4.0165 17.8317 3.92246 17.7369 3.85716 17.6231C3.79187 17.5092 3.75761 17.3801 3.75781 17.2489C3.75801 17.1176 3.79266 16.9887 3.8583 16.875C4.47611 15.8063 5.2533 13.1072 5.2533 9.75Z" stroke="#fff" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/>
        </svg>
        Напомнить о доступности
      </button>
      <button
        v-else
        class="product__cancel"
        @click="onCancel"
      >
        Отменить резерв
      </button>
    </div>


    <!-- Reserve Info BottomSheet -->
    <transition name="sheet">
      <div class="sheet-overlay" v-if="showReserveSheet" @click.self="showReserveSheet = false">
      <div class="sheet">
        <div class="sheet__handle" />

        <div class="sheet__illustration">
         <svg width="183" height="150" viewBox="0 0 183 150" fill="none" xmlns="http://www.w3.org/2000/svg">
<g clip-path="url(#clip0_51_18268)">
