.8625 103.538C62.8625 103.957 62.8948 104.376 62.927 104.763C63.1527 106.343 63.7654 107.633 64.4103 108.568C65.0552 109.503 65.7324 110.116 66.1838 110.503C66.3128 110.599 66.4095 110.696 66.5063 110.761C66.603 110.825 66.6675 110.89 66.732 110.922C66.861 111.019 66.9254 111.083 66.9254 111.083C66.9254 111.083 66.861 111.051 66.6997 110.986C66.6352 110.954 66.5385 110.89 66.4418 110.825C66.345 110.761 66.2483 110.696 66.1193 110.599C65.6356 110.245 64.894 109.632 64.2168 108.697C63.5397 107.762 62.8625 106.44 62.6045 104.795C62.5401 104.376 62.5078 103.957 62.5078 103.505C62.5078 103.28 62.5078 103.054 62.5723 102.796C62.6368 102.538 62.798 102.28 63.0882 102.151C63.3784 102.022 63.6687 102.087 63.9266 102.183C64.1846 102.28 64.4103 102.441 64.5715 102.635C64.9262 102.989 65.1842 103.441 65.5711 103.634L65.3132 103.925C64.7328 103.118 64.2491 102.183 63.9589 101.119C63.8299 100.603 63.7331 100.055 63.7009 99.507V99.2813C63.7009 99.2168 63.7009 99.0878 63.7009 98.9911V98.8298V98.7653C63.7009 98.7331 63.7331 98.7331 63.7654 98.7331C63.8621 98.6686 63.9589 98.6364 64.0556 98.6041C64.1523 98.6041 64.2813 98.6041 64.3781 98.6364C64.4748 98.6686 64.5715 98.7008 64.636 98.7653C64.7972 98.8943 64.9262 99.0878 64.9262 99.3135V100.507L64.4748 99.4102C63.9911 98.2494 63.5719 96.9918 63.2495 95.702C63.0882 95.0571 62.927 94.3799 62.8303 93.7028L62.7335 93.1869L62.7013 92.9289C62.7013 92.8967 62.7013 92.8322 62.7013 92.7677V92.5742V92.3807V92.284C62.7013 92.2517 62.669 92.2195 62.7335 92.2195C62.8625 92.155 62.9593 92.0905 63.1205 92.0905C63.2495 92.0583 63.4107 92.0905 63.5719 92.155C63.7009 92.2195 63.7976 92.284 63.8621 92.3807L63.4107 92.6064C63.0882 91.4134 62.927 90.188 62.927 88.9305C62.927 88.7692 62.927 88.608 62.927 88.4468L62.9593 88.1566C62.9593 88.0276 62.9915 87.8986 62.9915 87.7696V87.6729C62.9915 87.6406 62.9915 87.5762 63.0237 87.6084L63.2172 87.6406C63.3462 87.6406 63.4752 87.7051 63.6042 87.7051C63.7654 87.7374 63.7976 87.7696 63.8944 87.8019C63.9589 87.8341 