<script setup>
import { ref, computed, onMounted, onUnmounted } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { useCatalogueStore } from '../../stores/catalogueStore'
import { supabase } from '../../services/supabase'
import { storeToRefs } from 'pinia'
import { useFavourites } from '../../composables/useFavourites'

const route  = useRoute()
const router = useRouter()
const store  = useCatalogueStore()

const product       = ref(null)
const currentSlide  = ref(0)
const descExpanded  = ref(false)
const reservedCount = ref(0)

// ─── Locations из Supabase ───────────────────────────────────────────────────
const locations        = ref([])
const locationsLoading = ref(false)

const { isWishlisted: isWishlistedFn, toggleFavourite } = useFavourites()
const isWishlisted = computed(() => product.value ? isWishlistedFn(product.value.id) : false)
const fetchLocations = async () => {
  locations.value = [
    { id: 1, name: 'ТРЦ Forum', address: 'г. Алматы, пр. Достык 111' },
    { id: 2, name: 'ТРЦ Mega', address: 'г. Алматы, ул. Розыбакиева 247А' },
  ]
  try {
    const { data, error } = await supabase
      .from('locations')        // ← замените на название вашей таблицы
      .select('id, name, address')
      .order('name', { ascending: true })

    if (error) {
      console.error('Ошибка загрузки адресов:', error.message)
    } else {
      locations.value = data ?? []
    }
  } finally {
    locationsLoading.value = false
  }
}
// ────────────────────────────────────────────────────────────────────────────

const goToFond = () => {
  if (product.value?.fund_id) {
    router.push(`/fund/${product.value.fund_id}`)
  }
}
const _tx = ref(0)
const touchStart = (e) => { _tx.value = e.touches[0].clientX }
const touchEnd   = (e) => {
  const d = _tx.value - e.changedTouches[0].clientX
  if (Math.abs(d) < 40) return
  const max = images.value.length - 1
  currentSlide.value = d > 0
    ? Math.min(currentSlide.value + 1, max)
    : Math.max(currentSlide.value - 1, 0)
}

const catalogueStore = useCatalogueStore()
const { categories } = storeToRefs(catalogueStore)

const categoryName = computed(() => {
  if (!product.value?.category_id) return null
  const cat = categories.value.find(c => 
    String(c.id) === String(product.value.category_id)
  )
  return cat?.name || null
})
const images = computed(() => {
  if (!product.value) return []
  if (product.value.images?.length) return product.value.images
  if (product.value.image) return [product.value.image]
  return []
})

const shortName = computed(() => {
  if (!product.value?.name) return ''
  return product.value.name.split(' ').slice(0, 3).join(' ')
})

const formatPrice = (val) => Number(val).toLocaleString('ru-RU')

// Состояния: null | 'pending' | 'confirmed' | 'expired'
const reserveStatus = ref(null)
const timerSeconds  = ref(0)
let timerInterval   = null
let confirmTimeout  = null

const timerDisplay = computed(() => {
  const h = Math.floor(timerSeconds.value / 3600)
  const m = Math.floor((timerSeconds.value % 3600) / 60)
  const s = timerSeconds.value % 60
  return `${String(h).padStart(2,'0')}:${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`
})

const isReserved       = computed(() => reserveStatus.value !== null)
const showReserveSheet = ref(false)
const purchaseId       = ref(null)

const onReserve = () => {
  if (product.value?.stock > 0) {
    reservedCount.value = 1
    reserveStatus.value = 'pending'

    // Через 3 сек — подтверждение менеджера (зелёный таймер)
    confirmTimeout = setTimeout(() => {
      reserveStatus.value = 'confirmed'
      timerSeconds.value  = 1 * 60
      clearInterval(timerInterval)
      timerInterval = setInterval(() => {
        if (timerSeconds.value > 0) {
          timerSeconds.value--
          if (timerSeconds.value === 58 * 60) {
            reserveStatus.value = 'expired'
          }
        } else {
          clearInterval(timerInterval)
          reserveStatus.value = null
          reservedCount.value = 0
        }
      }, 1000)
    }, 3000)
  }
}
const goToNotifications = () => {
  router.push('/notifications')
}
const goToMyhelp = () => {
  router.push('/my-help')
}
const onCancel = async () => {
  if (purchaseId.value) {
    await supabase
      .from('purchases')
      .delete()
      .eq('id', purchaseId.value)
    purchaseId.value = null
  }
  reservedCount.value = 0
  reserveStatus.value = null
  timerSeconds.value  = 0
  clearInterval(timerInterval)
  clearTimeout(confirmTimeout)
}

const onNotify = () => {
  showReserveSheet.value = true
}

const onConfirmReserve = async () => {
  showReserveSheet.value = false

  const { data, error } = await supabase
    .from('purchases')
    .insert({ product_id: product.value.id, status: 'reserved' })
    .select()
    .single()

  if (error) {
    console.error('Ошибка сохранения покупки:', error.message)
  } else {
    purchaseId.value = data.id
    console.log('Покупка сохранена:', data)
  }
}

onMounted(async () => {
  // Загрузка продукта
  const id = route.params.id
  let found = store.products?.find(p => String(p.id) === String(id))
  if (found) {
    product.value = found
  } else {
    await store.fetchProduct?.(id)
    if (store.currentProduct) product.value = store.currentProduct
  }

  // Загрузка адресов из Supabase
  await fetchLocations()
})

onUnmounted(() => {
  clearInterval(timerInterval)
  clearTimeout(confirmTimeout)
})

</script>

